const {chromium,expect}=require(process.cwd()+'/node_modules/@playwright/test');
const fs=require('node:fs');
const assert=require('node:assert/strict');
const records=[];
(async()=>{
 const browser=await chromium.launch({headless:true});
 try{
  for(const width of [1440,390,320]){
   const page=await browser.newPage({viewport:{width,height:width===1440?900:844},isMobile:width<768,hasTouch:width<768});
   const errors=[];page.on('pageerror',e=>errors.push(e.message));
   const response=await page.goto('http://127.0.0.1:3010/service/feed');assert.equal(response.status(),200);
   await expect(page.getByText('아직 게시물이 없어요',{exact:true})).toBeVisible();
   const footer=page.locator('main footer');await expect(footer).toBeVisible();
   const links=await footer.locator('a').evaluateAll(nodes=>nodes.map(n=>({text:n.textContent,href:n.getAttribute('href')})));
   assert.deepEqual(links.map(x=>x.href),['/service/landing','/service/support','/service/notices','/service/studio']);
   const geometry=await page.evaluate(()=>{
    const footer=document.querySelector('main footer').getBoundingClientRect(),nav=document.querySelector('nav[aria-label="하단 메뉴"]');
    const main=document.querySelector('main').getBoundingClientRect();
    return {horizontalOverflow:document.documentElement.scrollWidth>innerWidth,footerBottom:footer.bottom,footerCenter:(footer.left+footer.right)/2,mainCenter:(main.left+main.right)/2,bottomNavTop:getComputedStyle(nav).display==='none'?innerHeight:nav.getBoundingClientRect().top};
   });
   assert.equal(geometry.horizontalOverflow,false);assert.ok(geometry.footerBottom<geometry.bottomNavTop);assert.ok(Math.abs(geometry.footerCenter-geometry.mainCenter)<1);
   if(width!==320)await page.screenshot({path:`docs/audit/empty-feed-${width===1440?'desktop':'mobile'}-20261022.png`});
   for(const {text,href} of links){
    await page.locator('main footer').getByRole('link',{name:text,exact:true}).click();await expect(page).toHaveURL('http://127.0.0.1:3010'+href);
    await expect(page.locator('body')).not.toContainText('Application error');
    await page.goto('http://127.0.0.1:3010/service/feed');await expect(page.getByText('아직 게시물이 없어요',{exact:true})).toBeVisible();
   }
   assert.deepEqual(errors,[]);records.push({width,scenario:'empty real local API feed, four footer destinations clicked',links,geometry,pageErrors:errors});await page.close();
  }
  const preview=await browser.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true});
  await preview.goto('http://127.0.0.1:3010/preview/feed');await expect(preview.locator('main article').first()).toBeVisible();await expect(preview.locator('main footer')).toHaveCount(0);
  records.push({scenario:'populated preview feed remains free of empty-state footer',passed:true});await preview.close();
 }finally{await browser.close();}
 fs.writeFileSync('/tmp/crefans-empty-feed-browser-result.json',JSON.stringify({time:new Date().toISOString(),records},null,2));console.log(JSON.stringify({passed:true,scenarios:records.length,viewportWidths:[1440,390,320],footerNavigationClicks:12}));
})().catch(e=>{console.error(e);process.exit(1)});
